const item = $input.first();
const mode = item.json['Mode'] || 'Tambah dokumen';
const binary = item.binary || {};
const keys = Object.keys(binary);
const canStore = mode === 'Tambah dokumen' || mode === 'Ganti semua knowledge';

const out = { json: { mode, hasFile: keys.length > 0, action: (keys.length > 0 && canStore) ? 'store' : 'manage' } };

if (keys.length > 0) {
  const b = binary[keys[0]];
  const fileName = b.fileName || 'dokumen';
  const ext = (b.fileExtension || fileName.split('.').pop() || '').toLowerCase();
  out.json.fileName = fileName;
  out.json.ext = ext;
  out.binary = { file: b };
}
return [out];

const MAX_CHARS_PER_DOC = 1000000;
const meta = $('Siapkan File').first().json;
const items = $input.all().map(i => i.json);
let text = '';

if (['xlsx', 'xls', 'csv'].includes(meta.ext)) {
  const headers = [...new Set(items.flatMap(r => Object.keys(r)))];
  const lines = ['Kolom: ' + headers.join(' | ')];
  items.forEach((r, idx) => {
    lines.push('Data #' + (idx + 1) + ': ' + headers.map(h => r[h] ?? '').join(' | '));
  });
  text = lines.join('\n');
} else {
  text = items.map(r => r.text ?? r.data ?? '').join('\n');
}

let truncated = false;
if (text.length > MAX_CHARS_PER_DOC) {
  text = text.slice(0, MAX_CHARS_PER_DOC);
  truncated = true;
}

return [{ json: { mode: meta.mode, fileName: meta.fileName, ext: meta.ext, text, truncated } }];

const doc = $('Gabung Teks').first().json;
const MAX = 2000;
const BATCH = 20;
const tabular = ['xlsx', 'xls', 'csv'].includes(doc.ext);
const rawLines = doc.text.split('\n');

let header = '';
let lines = rawLines;
if (tabular) { header = rawLines[0]; lines = rawLines.slice(1); }

// Setiap potongan diawali nama dokumen (+ header kolom untuk data tabel)
const prefix = '[Dokumen: ' + doc.fileName + ']\n' + (header ? header + '\n' : '');

const pieces = [];
for (const l of lines) {
  if (l.length > MAX) {
    for (let i = 0; i < l.length; i += MAX) pieces.push(l.slice(i, i + MAX));
  } else {
    pieces.push(l);
  }
}

const chunks = [];
let cur = [];
let len = 0;
for (const p of pieces) {
  if (len + p.length + 1 > MAX && cur.length) {
    chunks.push(cur.join('\n'));
    const last = cur[cur.length - 1];
    cur = (!tabular && last.length < 300) ? [last] : [];
    len = cur.reduce((a, b) => a + b.length + 1, 0);
  }
  cur.push(p);
  len += p.length + 1;
}
if (cur.length) chunks.push(cur.join('\n'));

let texts = chunks.filter(c => c.trim()).map(c => prefix + c);
if (!texts.length) texts = [prefix + '(dokumen kosong)'];

const out = [];
for (let i = 0; i < texts.length; i += BATCH) {
  out.push({ json: { texts: texts.slice(i, i + BATCH), start: i, fileName: doc.fileName } });
}
return out;

const batches = $('Buat Batch').all();
const embs = $input.all();
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

return embs.map((e, i) => {
  const b = batches[i].json;
  const vals = e.json.embeddings || [];
  if (vals.length !== b.texts.length) {
    throw new Error('Embedding gagal: ' + JSON.stringify(e.json).slice(0, 400));
  }
  const points = b.texts.map((t, k) => {
    const v = vals[k].values;
    if (!v || !v.length) throw new Error('Embedding kosong untuk potongan #' + (b.start + k));
    return { id: uuid(), vector: v, payload: { content: t, fileName: b.fileName, chunkIndex: b.start + k } };
  });
  return { json: { body: { points } } };
});

const doc = $('Gabung Teks').first().json;
const n = $('Susun Points').all().reduce((a, i) => a + i.json.body.points.length, 0);
const message = '✅ "' + doc.fileName + '" berhasil disimpan ke Qdrant (' + n + ' potongan teks)'
  + (doc.truncated ? ' — sebagian isi dipotong karena terlalu panjang' : '')
  + '.\n\nSekarang kamu bisa mulai chat. Untuk menambah dokumen lain atau melihat daftar knowledge, kirim form ini lagi.';
return [{ json: { message } }];

const MAX_CHARS = 800000;
const meta = $('Siapkan File').first().json;
const items = $input.all().map(i => i.json);
const headers = [...new Set(items.flatMap(r => Object.keys(r)))];
const lines = ['Kolom: ' + headers.join(' | ')];
items.forEach((r, idx) => {
  lines.push('Data #' + (idx + 1) + ': ' + headers.map(h => r[h] ?? '').join(' | '));
});
let text = lines.join('\n');
let truncated = false;
if (text.length > MAX_CHARS) {
  text = text.slice(0, MAX_CHARS) + '\n\n[CATATAN: tabel terlalu panjang, sebagian baris dipotong]';
  truncated = true;
}

const sd = $getWorkflowStaticData('global');
sd.tables = sd.tables || {};
if (meta.mode === 'Ganti semua knowledge') sd.tables = {};
sd.tables[meta.fileName] = {
  fileName: meta.fileName, text, rows: items.length, chars: text.length,
  uploadedAt: new Date().toISOString()
};

const message = '✅ Tabel "' + meta.fileName + '" (' + items.length + ' baris) disimpan langsung tanpa embedding'
  + (truncated ? ' — sebagian baris dipotong karena terlalu panjang' : '')
  + '.\n\nSekarang kamu bisa mulai chat.';
return [{ json: { message, mode: meta.mode } }];

const sd = $getWorkflowStaticData('global');
sd.tables = {};
return [{ json: { message: '🗑️ Semua knowledge (dokumen di Qdrant dan tabel) sudah dihapus.' } }];

const r = $input.first().json;
const pts = (r.result && r.result.points) || [];
const counts = {};
for (const p of pts) {
  const n = (p.payload && p.payload.fileName) || '(tanpa nama)';
  counts[n] = (counts[n] || 0) + 1;
}
const sd = $getWorkflowStaticData('global');
const tables = Object.values(sd.tables || {});

const lines = [];
Object.entries(counts).forEach(([n, c]) => lines.push(n + ' — dokumen, ' + c + ' potongan (Qdrant)'));
tables.forEach(t => lines.push(t.fileName + ' — tabel, ' + t.rows + ' baris (tanpa embedding)'));
if (!lines.length) return [{ json: { message: 'Belum ada knowledge tersimpan.' } }];

let message = 'Knowledge tersimpan:\n' + lines.map((l, i) => (i + 1) + '. ' + l).join('\n');
if (r.result && r.result.next_page_offset) message += '\n\n(Catatan: daftar dokumen Qdrant mungkin belum lengkap.)';
return [{ json: { message } }];

const MAX_DOC = 60000;
const MAX_TABLE = 800000;
const chat = $('Chat Trigger').first().json;
const r = $input.first().json;
const raw = r.result && (r.result.points || r.result);
const hits = Array.isArray(raw) ? raw : [];
const files = new Set();

let docText = '';
hits.forEach((h, i) => {
  const p = h.payload || {};
  if (p.fileName) files.add(p.fileName);
  const skor = (typeof h.score === 'number') ? h.score.toFixed(3) : '-';
  const block = '--- Potongan ' + (i + 1) + ' (skor ' + skor + ') ---\n' + (p.content || '') + '\n\n';
  if (docText.length + block.length > MAX_DOC) return;
  docText += block;
});

const sd = $getWorkflowStaticData('global');
const tables = Object.values(sd.tables || {});
let tableText = '';
for (const t of tables) {
  const block = '=== TABEL: ' + t.fileName + ' ===\n' + t.text + '\n\n';
  if (tableText.length + block.length > MAX_TABLE) {
    tableText += '[CATATAN: tabel terlalu banyak, sebagian tidak dimuat]';
    break;
  }
  tableText += block;
  files.add(t.fileName);
}

return [{ json: {
  sessionId: chat.sessionId,
  chatInput: chat.chatInput,
  fileName: [...files].join(', '),
  tableText,
  documentText: docText
} }];

const item = $input.first().json;
// Webhook n8n membungkus data Evolution di body: { event, instance, data: {...} }
const body = item.body || item;
if (body.event && body.event !== 'messages.upsert') return [];

const data = body.data || {};
const key = data.key || {};
const msg = data.message || {};
let jid = key.remoteJid || '';

// Ambil teks dari beberapa tipe pesan
const text = (
  msg.conversation ||
  (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
  (msg.imageMessage && msg.imageMessage.caption) ||
  (msg.videoMessage && msg.videoMessage.caption) ||
  ''
).toString().trim();

// Abaikan pesan sendiri, pesan kosong, status/broadcast, atau chat grup
if (key.fromMe || !text || jid === 'status@broadcast' || jid.endsWith('@broadcast') || jid.endsWith('@g.us')) {
  return [];
}

// Beberapa versi memakai ID @lid; pakai nomor asli jika tersedia
if (jid.endsWith('@lid') && key.remoteJidAlt) jid = key.remoteJidAlt;

const sender = jid.split('@')[0];
const number = jid.endsWith('@s.whatsapp.net') ? sender : jid;
return [{ json: { chatId: jid, number, sender, text } }];

const MAX_DOC = 60000;
const MAX_TABLE = 800000;
const wa = $('Filter Pesan WA').first().json;
const r = $input.first().json;
const raw = r.result && (r.result.points || r.result);
const hits = Array.isArray(raw) ? raw : [];
const files = new Set();

let docText = '';
hits.forEach((h, i) => {
  const p = h.payload || {};
  if (p.fileName) files.add(p.fileName);
  const skor = (typeof h.score === 'number') ? h.score.toFixed(3) : '-';
  const block = '--- Potongan ' + (i + 1) + ' (skor ' + skor + ') ---\n' + (p.content || '') + '\n\n';
  if (docText.length + block.length > MAX_DOC) return;
  docText += block;
});

const sd = $getWorkflowStaticData('global');
const tables = Object.values(sd.tables || {});
let tableText = '';
for (const t of tables) {
  const block = '=== TABEL: ' + t.fileName + ' ===\n' + t.text + '\n\n';
  if (tableText.length + block.length > MAX_TABLE) {
    tableText += '[CATATAN: tabel terlalu banyak, sebagian tidak dimuat]';
    break;
  }
  tableText += block;
  files.add(t.fileName);
}

return [{ json: {
  sessionId: wa.chatId,
  chatId: wa.chatId,
  chatInput: wa.text,
  fileName: [...files].join(', '),
  tableText,
  documentText: docText
} }];
